(1233,	265,	'_form',	'<label>Contact Name (required)\n    [text* contact-name class:form-control placeholder \"Contact Name\"]\n</label>\n<label>Store Name (required)\n    [text* junkyard-name class:form-control placeholder \"Store Name\"]\n</label>\n<label>Location  (required)\n    [text* your-location class:form-control placeholder \"Location\"]\n</label>\n<label>Phone Number(required)\n    [text* your-phone class:form-control placeholder \"Phone\"]\n</label>\n\n<label>Category\n    [select category class:form-control \"Retail store\" \"Scrapyard\"]\n</label>\n<label>Message\n    [textarea message  class:form-control placeholder \"Message\"]\n</label>\n\n[submit class:btn-submit \"Send\"]'),
(1234,	265,	'_mail',	'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:32:\"Seller Inquiry - [junkyard-name]\";s:6:\"sender\";s:35:\"[_site_title] <no-reply@seeeda.com>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:290:\"Hi Admin,\n\nWe have received the below inquiry\n\nContact Name: [contact-name]\nStore: [junkyard-name]\nLocation: [your-location]\nPhone: [your-phone]\nCategory: [category]\nMessage: [message]\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\";s:18:\"additional_headers\";s:0:\"\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(1235,	265,	'_mail_2',	'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:36:\"[_site_title] <wordpress@seeeda.com>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:220:\"Message Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
