(3788,	860,	'_form',	'<label>اسم جهة الاتصال (مطلوب)\n    [text* contact-name class:form-control placeholder \"اسم جهة الاتصال\"]\n</label>\n<label>اسم المتجر (required)\n    [text* junkyard-name class:form-control placeholder \"اسم المتجر\"]\n</label>\n<label>الموقع (مطلوب)\n    [text* your-location class:form-control placeholder \"موقع\"]\n</label>\n<label>رقم الهاتف (مطلوب)\n    [text* your-phone class:form-control placeholder \"رقم الهاتف\"]\n</label>\n\n<label>فئة\n    [select category class:form-control \"متجر بيع بالتجزئة\" \"ساحة الخردة\"]\n</label>\n<label>رسالة\n    [textarea message  class:form-control placeholder \"رسالة\"]\n</label>\n\n[submit class:btn-submit \"أرسل\"]'),
(3789,	860,	'_mail',	'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:32:\"Seller Inquiry - [junkyard-name]\";s:6:\"sender\";s:35:\"[_site_title] <no-reply@seeeda.com>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:290:\"Hi Admin,\n\nWe have received the below inquiry\n\nContact Name: [contact-name]\nStore: [junkyard-name]\nLocation: [your-location]\nPhone: [your-phone]\nCategory: [category]\nMessage: [message]\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\";s:18:\"additional_headers\";s:0:\"\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
